from pathlib import Path
import json
R=Path(__file__).resolve().parent;A=R.parents[1]
scene=json.loads((R/'vendor/just-zjg-campus/scene-calibrated.json').read_text(encoding='utf-8'))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>张家港校区 · 建筑位置示意图</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f5f5;color:#17191b;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}header{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:22px 28px;border-bottom:1px solid #ddd;background:#fff}h1{font-size:22px;font-weight:600;margin:0}header p{margin:3px 0 0;color:#62676b;font-size:12px}button,select{font:inherit;color:inherit;background:#fff;border:1px solid #d6d9db;border-radius:999px;padding:10px 16px;min-height:44px;cursor:pointer}button[aria-pressed=true]{background:#191b1d;color:#fff}nav{display:flex;gap:8px;flex-wrap:wrap}main{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:20px;padding:24px;max-width:1600px;margin:auto}.stage{height:min(70vh,760px);min-height:360px;position:relative;overflow:hidden;border-radius:24px;background:#e8ebed;border:1px solid #d7dcdf}canvas,svg{display:block;width:100%;height:100%}svg{background:#e8ebed}svg[hidden],canvas[hidden]{display:none}.lamp{position:absolute;width:10px;height:10px;background:#25c86e;border:2px solid white;box-shadow:0 0 0 4px #25c86e33;transform:translate(-50%,-50%);pointer-events:none}.lamp[data-state=current]{animation:breathe 1.8s ease-in-out infinite}.lamp[data-state=done]{background:#8d969d;box-shadow:0 0 0 4px #8d969d33}.lamp[hidden]{display:none}@keyframes breathe{50%{opacity:.4;box-shadow:0 0 0 7px #25c86e18}}aside{padding:12px 4px}aside h2{font-size:17px;margin:0 0 16px}aside label{display:block;margin-bottom:18px}aside label span{display:block;font-size:12px;color:#5e6469;margin-bottom:6px}select{border-radius:12px;max-width:100%;width:100%;padding:10px}#targetName{font-size:19px;font-weight:600;margin:20px 0 4px}#targetNote{color:#5d666d;font-size:12px;margin:0}.meta{font-size:11px;color:#62696e;line-height:1.8;padding:0 28px 24px;max-width:1500px;margin:auto}.legend{display:flex;flex-direction:column;gap:8px;margin-top:24px;font-size:12px}.legend i{display:inline-block;width:7px;height:7px;background:#25c86e;margin-right:8px}.legend .past{background:#8d969d}.plan-label{font:9px sans-serif;fill:#3f4a53;paint-order:stroke;stroke:#fff;stroke-width:2px;stroke-linejoin:round}.gym-front[hidden]{display:none}.gym-front{margin:12px 0;grid-column:1/-1;justify-self:start}.plan-building{fill:#fff;stroke:#abb7bf;stroke-width:1}.plan-building.is-target{stroke:#25a860;stroke-width:3}@media(max-width:700px){main{grid-template-columns:1fr;padding:14px;gap:8px}header{padding:18px}.stage{height:280px;min-height:240px}aside{display:grid;grid-template-columns:1fr 1fr;gap:12px}aside h2,.legend{display:none}#targetName,#targetNote{grid-column:1/-1;margin:0}.meta{padding:12px 18px}}@media(prefers-reduced-motion:reduce){.lamp{animation:none!important}}

:root{--paper:#F5F5F4;--card:#FFFFFF;--ink:#1B1B1A;--ink-2:#6E6E6A;--line:#E4E4E0;--line-2:#EFEFEC;--accent:#1D9E75;--glow:#1D9E7533;--past:#9C9C97;--map-ground:#EAEAE7;--map-road:#D4D4CF;--map-water:#DEDEDA;--map-field:#E4E4DF}
html[data-theme=dark]{color-scheme:dark;--paper:#131312;--card:#1C1C1B;--ink:#EDEDE8;--ink-2:#A3A39E;--line:#2D2D2B;--line-2:#242423;--accent:#34C48F;--glow:#34C48F33;--past:#6E6E6A;--map-ground:#1C1C1B;--map-road:#363633;--map-water:#262625;--map-field:#242423}
body{background:var(--paper);color:var(--ink)}header{background:var(--card);border-color:var(--line)}header p,aside label span,#targetNote,.meta{color:var(--ink-2)}button,select{background:var(--card);border-color:var(--line);color:var(--ink)}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.stage{background:var(--paper);border-color:var(--line)}svg{background:var(--paper)}.palette{display:flex;gap:3px;padding:3px;background:var(--line-2);border-radius:999px}.palette button{border:0;min-height:38px;padding:7px 13px;background:transparent}.palette button[aria-pressed=true]{background:var(--card);color:var(--ink)}.lamp{background:var(--accent);box-shadow:0 0 0 4px var(--glow)}.lamp[data-state=done]{background:var(--past);box-shadow:0 0 0 4px #9C9C9722}.legend i{background:var(--accent)}.legend .past{background:var(--past)}@keyframes breathe{50%{opacity:.4;box-shadow:0 0 0 7px var(--glow)}}.gym-front[hidden]{display:none}.gym-front{margin:12px 0;grid-column:1/-1;justify-self:start}.plan-building{fill:#fff;stroke:#9C9C97}.plan-building.is-target{stroke:var(--accent)}button:focus-visible,select:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
</style><header><div><h1>张家港校区</h1><p>建筑位置示意图 · 等角轴测 · 黑白像素</p></div><nav><button id="overview" aria-pressed="true">轴测全景</button><button id="plan" aria-pressed="false">平面核对</button><button id="replay">重播定位</button><div class="palette" role="group" aria-label="主题预览"><button id="lightTheme" aria-pressed="true">浅色</button><button id="darkTheme" aria-pressed="false">深色</button></div></nav></header><main><section class="stage" id="stage"><canvas id="scene" aria-label="校园白色像素建筑模型"></canvas><i class="lamp" id="lamp" data-state="upcoming" hidden></i><svg id="flatPlan" hidden viewBox="-170 -45 1200 905" aria-label="按照片透视校正后的校园平面布局"></svg></section><aside><h2>查看建筑</h2><label><span>楼栋</span><select id="building"><option value="">校园全景</option></select></label><label><span>课程状态预览</span><select id="status"><option value="upcoming">未开始 · 绿色常亮</option><option value="current">正在上课 · 绿色呼吸</option><option value="done">已结束 · 灰色</option></select></label><p id="targetName">校园全景</p><p id="targetNote">45 个建筑 · 2 处商业区域</p><button id="gymFront" class="gym-front" hidden>正门视角</button><div class="legend"><span><i></i>未开始：绿色常亮</span><span><i></i>正在上课：绿色呼吸</span><span><i class="past"></i>已结束：灰色</span></div></aside></main><p class="meta">E、F、G、H 已拆分为独立楼栋；其余分区、道路与水系按所提供的校园平面图调整。图书馆采用规则对称椭圆，其余楼栋规整为矩形、直角转折或对称梯形；高度参考 23 张官方图片与校友航拍估算；图书馆檐口、体育馆下包式曲壳、独立入口雨棚和台阶、行政楼顶部框架和宿舍屋顶已作简化建模。<br>建筑位置示意，非导航或测量图。原始基础数据 © OpenStreetMap contributors（ODbL）；平面校正记录随源码保留。</p>'''
html+='<script>'+''.join((R/f).read_text(encoding='utf-8') for f in ['campus-data.js','campus-core.js','campus-massing.js','campus-renderer.js'])+'</script>'
html+='<script>const PLAN='+json.dumps(scene,ensure_ascii=False,separators=(',',':'))+';\n'
html+='''const $=id=>document.getElementById(id),S=SuikeCampusScene,C=SuikeCampusCore,r=SuikeCampusRenderer.create($('scene'),$('lamp'),S,C);let flat=false,selected='';
function size(){const b=$('stage').getBoundingClientRect();r.resize(b.width,b.height)}r.setActive(true);size();window.addEventListener('resize',size);
function element(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs||{}).forEach(([k,v])=>el.setAttribute(k,v));return el}
const svg=$('flatPlan');function poly(pts,attrs){const p=element('polygon',Object.assign({points:pts.map(v=>v[0]+','+(800-v[1])).join(' ')},attrs));svg.append(p);return p}
poly(PLAN.site,{fill:'var(--map-ground)'});PLAN.waters.forEach(w=>poly(w.pts,{fill:'var(--map-water)'}));PLAN.roads.forEach(road=>{svg.append(element('polyline',{points:road.pts.map(v=>v[0]+','+(800-v[1])).join(' '),fill:'none',stroke:'var(--map-road)','stroke-width':road.width,'stroke-linejoin':'round'}));});
PLAN.features.forEach(f=>{const [x,y]=f.center;poly([[x-f.w/2,y-f.h/2],[x+f.w/2,y-f.h/2],[x+f.w/2,y+f.h/2],[x-f.w/2,y+f.h/2]],{fill:'var(--map-field)',stroke:'var(--map-road)'});});
(PLAN.zones||[]).forEach(z=>poly(z.pts,{fill:'none',stroke:'var(--ink-2)','stroke-width':1.8,'stroke-dasharray':'9 7','data-zone':z.id}));
PLAN.tracks.forEach(t=>{svg.append(element('ellipse',{cx:t.center[0],cy:800-t.center[1],rx:t.short/2,ry:t.long/2,fill:'var(--map-field)',stroke:'var(--map-road)','stroke-width':5}));});
S.buildings.forEach(b=>{const source=PLAN.buildings.find(p=>p.id===b.id),p=poly(source.pts,{class:'plan-building','data-id':b.id});p.addEventListener('click',()=>select(b.id));if(b.name==='运动场附属建筑')return;const text=element('text',{x:b.anchor[0],y:800-b.anchor[1],'text-anchor':'middle','dominant-baseline':'middle',class:'plan-label'});text.textContent=b.name;svg.append(text);const option=document.createElement('option');option.value=b.id;option.textContent=b.name;$('building').append(option);});
function select(id,animate=true,roof=false){selected=id;$('building').value=id;$('gymFront').hidden=id!=='osm-260623895';const b=S.buildings.find(b=>b.id===id);r[roof?'focus':'inspect'](b?{building:b}:null,animate&&!matchMedia('(prefers-reduced-motion:reduce)').matches);$('targetName').textContent=b?b.name:'校园全景';$('targetNote').textContent=b?'约 '+b.height+' 米 · 高度估算':'45 个建筑 · 2 处商业区域';svg.querySelectorAll('.plan-building').forEach(p=>p.classList.toggle('is-target',p.dataset.id===id));}
$('gymFront').onclick=()=>{mode(false);r.entrance({building:S.buildings.find(b=>b.id==='osm-260623895')},!matchMedia('(prefers-reduced-motion:reduce)').matches)};
$('building').addEventListener('change',()=>select($('building').value));$('status').addEventListener('change',()=>{$('lamp').dataset.state=$('status').value});function mode(value){flat=value;$('scene').hidden=flat;svg.toggleAttribute('hidden',!flat);$('lamp').hidden=flat||!selected;r.setActive(!flat&&!document.hidden);$('overview').setAttribute('aria-pressed',String(!flat));$('plan').setAttribute('aria-pressed',String(flat));if(!flat){size();r.overview(false);select(selected,false);}}
$('overview').onclick=()=>{mode(false);select('')};$('plan').onclick=()=>mode(true);$('replay').onclick=()=>{mode(false);r.overview(false);setTimeout(()=>select(selected||'plan-teaching-E',true,true),180)};document.addEventListener('visibilitychange',()=>r.setActive(!document.hidden&&!flat));
function palette(value){const dark=value==='dark';document.documentElement.dataset.theme=dark?'dark':'light';r.setPalette(dark?'dark':'light');$('lightTheme').setAttribute('aria-pressed',String(!dark));$('darkTheme').setAttribute('aria-pressed',String(dark));}
$('lightTheme').onclick=()=>palette('light');$('darkTheme').onclick=()=>palette('dark');palette(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');
window.CampusPreview={renderer:r,select,mode,palette,scene:S};
const params=new URLSearchParams(location.search),initial=params.get('building');if(S.buildings.some(b=>b.id===initial)){select(initial,false);if(initial==='osm-260623895'&&params.get('view')==='front')r.entrance({building:S.buildings.find(b=>b.id===initial)},false);}
'''+'</script></html>'
(A/'建筑示意图预览.html').write_text(html,encoding='utf-8',newline='\n')
(A/'体育馆校正预览.html').write_text(html.replace("initial=params.get('building')", "initial=params.get('building')||'osm-260623895'").replace("params.get('view')==='front'", "params.get('view')!=='iso'"),encoding='utf-8',newline='\n')
(R/'assets/campus-preview.html').write_text(html,encoding='utf-8',newline='\n')
print('Standalone calibrated 3D / plan-comparison preview written.')
